mapper.select:
SELECT 
FROM workflow_tasks
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY id DESC

SELECT t.id, t.title, t.content, t.status, t.project_id, t.agent_id, t.start_time,
       t.execution_period, t.reject_reason, t.user_id, t.create_time, t.update_time,
       a.name AS agent_name, p.name AS project_name
FROM workflow_tasks t
LEFT JOIN agents a ON t.agent_id = a.id
LEFT JOIN projects p ON t.project_id = p.id
WHERE t.user_id = #{userId}

    AND (t.title LIKE CONCAT('%', #{keyword}, '%') OR t.content LIKE CONCAT('%', #{keyword}, '%'))


    AND t.status = #{status}


    AND t.project_id = #{projectId}


    AND t.agent_id = #{agentId}

ORDER BY t.create_time DESC, t.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM workflow_tasks
WHERE user_id = #{userId}

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND project_id = #{projectId}


    AND agent_id = #{agentId}
